#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using Oculus.Interaction;using Oculus.Interaction.HandGrab;
namespace VRMaintenanceResearch.HandsLabQuest3.Editor {
public static partial class HandsLabEditor {
static partial void RuntimeCommand(string command){if(command=="objects")AddObjects();else if(command=="capture")Capture("editor_handslab");else if(command=="scene_probe")SceneProbe();else if(command=="play"){Guard();EditorApplication.isPlaying=true;}else if(command=="stop"){EditorApplication.isPlaying=false;}else if(command=="reopen"){Guard();EditorSceneManager.OpenScene(ScenePath);SceneProbe();}else CompleteCommand(command);}
static partial void CompleteCommand(string command);
static void AddObjects(){Guard();if(SceneManager.GetActiveScene().path!=ScenePath)throw new Exception("Wrong scene");var active=SceneManager.GetActiveScene();var parent=GameObject.Find("HandsLab_Quest3").transform;if(parent.Find("PinchStone"))throw new Exception("Objects already exist");var sample=EditorSceneManager.OpenScene(Root+"/Editor/ReferenceSample.unity",OpenSceneMode.Additive);try{SceneManager.SetActiveScene(active);foreach(var pair in new[]{new[]{"Stone-HandToInteractable","PinchStone"},new[]{"SimpleGrab4ComboGrab","GripHandle"}}){var src=sample.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).First(t=>t.name==pair[0]&&t.GetComponent<Rigidbody>());var clone=UnityEngine.Object.Instantiate(src.gameObject,parent);clone.name=pair[1];clone.transform.position=pair[1]=="PinchStone"?new Vector3(-.25f,.85f,.49f):new Vector3(.25f,.85f,.49f);clone.transform.rotation=Quaternion.identity;clone.SetActive(true);var rb=clone.GetComponent<Rigidbody>();rb.useGravity=true;rb.isKinematic=false;rb.mass=.15f;rb.linearDamping=.5f;rb.angularDamping=.8f;rb.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;foreach(var h in clone.GetComponentsInChildren<HandGrabInteractable>(true)){h.HandAlignment=HandAlignType.AlignOnGrab;var so=new SerializedObject(h);var max=so.FindProperty("_maxSelectingInteractors");if(max!=null)max.intValue=1;so.ApplyModifiedPropertiesWithoutUndo();}foreach(var g in clone.GetComponentsInChildren<Grabbable>(true)){g.MaxGrabPoints=1;g.InjectOptionalRigidbody(rb);g.InjectOptionalKinematicWhileSelected(true);g.InjectOptionalThrowWhenUnselected(false);}foreach(var c in clone.GetComponentsInChildren<MonoBehaviour>(true)){if(c&& (c.GetType().Name.Contains("SnapInteractable")||c.GetType().Name.Contains("Audio")||c.GetType().Name.Contains("DistanceGrabInteractable")))c.enabled=false;}}}finally{EditorSceneManager.CloseScene(sample,true);}EditorSceneManager.SaveScene(active);SceneProbe();Capture("editor_objects");}
static void SceneProbe(){var s=SceneManager.GetActiveScene();Write("scene_probe",new{scene=s.path,s.isDirty,playing=EditorApplication.isPlaying,cameras=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsInactive.Include,FindObjectsSortMode.None).Select(c=>new{path=PathOf(c.transform),c.enabled}).ToArray(),objects=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.GetComponent<Rigidbody>()||t.GetComponent<SkinnedMeshRenderer>()||t.GetComponent<HandGrabInteractable>()).Select(t=>new{path=PathOf(t),active=t.gameObject.activeInHierarchy,position=new[]{t.position.x,t.position.y,t.position.z},scale=new[]{t.lossyScale.x,t.lossyScale.y,t.lossyScale.z},poses=t.GetComponentsInChildren<HandGrabPose>(true).Length,mesh=t.GetComponent<SkinnedMeshRenderer>()&&t.GetComponent<SkinnedMeshRenderer>().sharedMesh?t.GetComponent<SkinnedMeshRenderer>().sharedMesh.name:null,types=t.GetComponents<Component>().Where(c=>c).Select(c=>c.GetType().FullName).ToArray()})});}
static void Capture(string filename){var camera=UnityEngine.Object.FindFirstObjectByType<Camera>();if(!camera)throw new Exception("Camera missing");var go=new GameObject("HandsLab_EvidenceCamera");go.hideFlags=HideFlags.HideAndDontSave;var c=go.AddComponent<Camera>();c.CopyFrom(camera);c.transform.position=new Vector3(1.05f,1.6f,-.6f);c.transform.LookAt(new Vector3(0,1,.60f));var rt=new RenderTexture(1600,1000,24);var previous=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;var tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(Out+"/"+filename+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{RenderTexture.active=previous;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
}}
#endif

